import{_ as o,o as a,c as s,a2 as t}from"./chunks/framework.BDCokyix.js";const h=JSON.parse('{"title":"Packaging and Deployment","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/deployment.md","filePath":"architecture/deployment.md","lastUpdated":1780254295000}'),r={name:"architecture/deployment.md"};function d(i,e,n,c,l,p){return a(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="packaging-and-deployment" tabindex="-1">Packaging and Deployment <a class="header-anchor" href="#packaging-and-deployment" aria-label="Permalink to &quot;Packaging and Deployment&quot;">​</a></h1><p>Soma ships as <strong>two artifacts</strong>: one Tauri V2 desktop app and one server binary (<code>somad</code>). Both are thin shells around the same shared Rust crates — the desktop embeds them in its <code>src-tauri</code> host process via the <code>desktop-*</code> crates, the server runs them as subcommands of a unified binary. This page summarizes how each is packaged and operated.</p><h2 id="desktop-application-packaging" tabindex="-1">Desktop Application Packaging <a class="header-anchor" href="#desktop-application-packaging" aria-label="Permalink to &quot;Desktop Application Packaging&quot;">​</a></h2><ul><li><strong>Targets</strong> – macOS <code>arm64</code> (notarized <code>.dmg</code> + <code>.zip</code>) and Linux <code>amd64</code> + <code>arm64</code> (<code>.deb</code> + <code>.AppImage</code>). Windows is not supported.</li><li><strong>Contents</strong> – a single Tauri V2 bundle built from <code>desktop/desktop-app/</code>. The React/Vite renderer plus the Rust <code>src-tauri</code> host (composed from the <code>desktop-*</code> crates) ship as one app; the peer and agent runtimes are embedded in-process inside the host binary. There are <strong>no separate daemon or agent binaries</strong> and no native <code>.node</code> addon.</li><li><strong>Build tooling</strong> – the <strong>Tauri bundler</strong> (<code>tauri build</code>) drives both the renderer build and the macOS/Linux bundle/sign/notarize steps. No <code>electron-builder</code>, no <code>@napi-rs/cli</code>, no external <code>desktop/packaging/</code> tooling, no <code>@soma/packaging</code> CLI.</li><li><strong>macOS signing + notarization</strong> – the Tauri bundler signs with a <strong>Developer ID Application</strong> certificate and notarizes via <code>notarytool</code> (credentials are passed from the workflow&#39;s Apple secrets). It produces a notarized <code>.dmg</code> (open and drag <code>Soma.app</code> into Applications) and a notarized <code>.zip</code> (unzip <code>Soma.app</code> anywhere). No <code>/Library/LaunchAgents</code>, no <code>pkgbuild</code>, no sudo, no <code>xattr</code> quarantine stripping, no install/uninstall scripts.</li><li><strong>Linux</strong> – one <code>.deb</code> and one <code>.AppImage</code> per arch published to the GitHub Release. Install the <code>.deb</code> with <code>sudo apt install ./soma-desktop-linux-&lt;arch&gt;.deb</code>; or <code>chmod +x</code> the <code>.AppImage</code> and run it directly. No systemd unit is shipped; autostart is the user&#39;s choice (a <code>~/.config/autostart/</code> <code>.desktop</code> file is the conventional path).</li><li><strong>Release pipeline</strong> – <code>.github/workflows/release-desktop.yml</code> (<code>workflow_dispatch</code>) reads the <code>(os, arch)</code> matrix from <code>.github/targets.json</code>, builds the <code>desktop/desktop-app/</code> bundles via <code>tauri-apps/tauri-action</code>, signs + (on macOS) notarizes, renames the bundles to the versionless <code>soma-desktop-&lt;os&gt;-&lt;arch&gt;.&lt;ext&gt;</code> convention, and publishes them to a <code>desktop-v*</code> GitHub Release alongside a <code>SHA256SUMS</code> file. (The macOS signing/notarization path was confirmed by a real <code>workflow_dispatch</code> run.)</li><li><strong>Login items</strong> – a macOS Login Item / autostart is registered when the user opts in; the peer is alive only while the process is running, and the macOS tray keeps it live after the window closes.</li></ul><p>The embedded peer is online only while Soma is open. Long-term availability for a space is provided by a <code>somad bot</code> running as a space mirror — see &quot;Supporting Infrastructure&quot; below.</p><h2 id="server-somad" tabindex="-1">Server: <code>somad</code> <a class="header-anchor" href="#server-somad" aria-label="Permalink to &quot;Server: `somad`&quot;">​</a></h2><p>One binary, subcommand-dispatched. Modes are selected at runtime; behavior shared across all of them (clap CLI + env, <code>mimalloc</code>, <code>tracing</code>) is unified.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>somad bot         [--http-addr ...] [--db-url ...] [--listen-addrs ...] [--mode bot|admin]</span></span>\n<span class="line"><span>somad relay       [--http-addr ...]</span></span>\n<span class="line"><span>somad rendezvous  [--http-addr ...]</span></span>\n<span class="line"><span>somad bff         [--http-addr ...] [--p2p-enable]</span></span>\n<span class="line"><span>somad all         --config server.toml      # composes multiple modes in one process</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Each subcommand also accepts a <code>generate-identity</code> action where applicable (<code>somad relay generate-identity</code>, <code>somad rendezvous generate-identity</code>, <code>somad bot generate-identity</code>) for one-shot keypair creation. <code>SOMA_DATA_DIR</code> (env) anchors the persisted libp2p identity files; see <code>somad &lt;subcommand&gt; --help</code> for the authoritative flag list.</p><p>Packaging:</p><ul><li><strong>One image</strong> — <code>ghcr.io/&lt;owner&gt;/somad</code>. Built from one <code>Dockerfile</code> (no per-service targets).</li><li><strong>Base</strong> — <code>gcr.io/distroless/static-debian12:nonroot</code>.</li><li><strong>Multi-arch</strong> — <code>amd64</code> + <code>arm64</code>, built from prebuilt MUSL binaries copied in (no Rust compile during <code>docker build</code>).</li><li><strong>Release pipeline</strong> — <code>.github/workflows/release-server.yml</code> (<code>workflow_dispatch</code>) reads the server slice of <code>.github/targets.json</code> and publishes one image, runtime-multiplexed by subcommand.</li></ul><p>Mode is selected at runtime via the entrypoint args, e.g. <code>docker run ghcr.io/.../somad bot --http-addr 0.0.0.0:8080 ...</code>.</p><h2 id="supporting-infrastructure" tabindex="-1">Supporting Infrastructure <a class="header-anchor" href="#supporting-infrastructure" aria-label="Permalink to &quot;Supporting Infrastructure&quot;">​</a></h2><p>The same <code>somad</code> image provides every server-side role; each subcommand is its own Helm release.</p><h3 id="rendezvous-server" tabindex="-1">Rendezvous Server <a class="header-anchor" href="#rendezvous-server" aria-label="Permalink to &quot;Rendezvous Server&quot;">​</a></h3><ul><li><code>somad rendezvous</code> runs the libp2p rendezvous discovery protocol, letting peers register under namespaces like <code>soma-prod</code> or <code>soma-dev</code>.<a href="https://docs.libp2p.io/concepts/discovery-routing/rendezvous/" target="_blank" rel="noreferrer">^rendezvous</a></li><li>Deployed via Helm, usually as a simple Deployment with a public LoadBalancer Service exposing TCP/QUIC/WS ports.</li><li>Identity persists at <code>${SOMA_DATA_DIR}/rendezvous/identity.key</code> so the Peer ID is stable across restarts (back it with a Kubernetes Secret or PVC).</li><li>Exposes <code>GET /healthz</code> and <code>GET /metrics</code> (Prometheus); metrics are prefixed <code>rendezvous_</code>.</li></ul><h3 id="circuit-relay-nodes" tabindex="-1">Circuit Relay Nodes <a class="header-anchor" href="#circuit-relay-nodes" aria-label="Permalink to &quot;Circuit Relay Nodes&quot;">​</a></h3><ul><li><code>somad relay</code> provides <code>/p2p-circuit</code> addresses for peers that cannot accept inbound connections because of restrictive NAT or firewalls.<a href="https://docs.libp2p.io/concepts/nat/circuit-relay/" target="_blank" rel="noreferrer">^relay</a></li><li>Multiple relay pods can be deployed for redundancy; each persists its libp2p identity at <code>${SOMA_DATA_DIR}/relay/identity.key</code> so the Peer ID survives restarts.</li><li>Peers discover relays via static config or rendezvous announcements and attempt hole punching (DCUtR) to upgrade connections whenever possible.</li><li>Exposes <code>GET /healthz</code> and <code>GET /metrics</code>; metrics are prefixed <code>relay_</code>.</li></ul><h3 id="llm-bff-somad-bff" tabindex="-1">LLM BFF (<code>somad bff</code>) <a class="header-anchor" href="#llm-bff-somad-bff" aria-label="Permalink to &quot;LLM BFF (`somad bff`)&quot;">​</a></h3><ul><li>HTTP-only provider integration for LLMs (no libp2p by default). Listens on <code>0.0.0.0:8083</code> and exposes <code>/metrics</code>; the BFF API itself is served on the same port.</li><li><code>--p2p-enable</code> turns on an optional diagnostic libp2p peer for testing — off in production.</li><li>Deployed via Helm like the other services; horizontally scalable behind a normal Service/Ingress since it holds no peer state.</li></ul><h3 id="optional-hosted-bots" tabindex="-1">Optional Hosted Bots <a class="header-anchor" href="#optional-hosted-bots" aria-label="Permalink to &quot;Optional Hosted Bots&quot;">​</a></h3><ul><li><code>somad bot</code> (<code>--mode bot|admin</code>) provides always-on availability for a space (a &quot;space mirror&quot;). The same image runs as a headless peer + cache, configured via flags/env for <code>SOMA_DATABASE_URL</code>, libp2p listen addrs, and (in <code>admin</code> mode) the authenticated control-plane endpoints under <code>/v1/*</code>. The cache/announce semantics are described in <a href="https://github.com/stephane-segning/soma/blob/main/AGENTS.md#bots-and-always-on-availability" target="_blank" rel="noreferrer">AGENTS.md § &quot;Bots and always-on availability&quot;</a>.</li></ul><h2 id="release-and-operations-workflow" tabindex="-1">Release and Operations Workflow <a class="header-anchor" href="#release-and-operations-workflow" aria-label="Permalink to &quot;Release and Operations Workflow&quot;">​</a></h2><ol><li>Build, sign, and notarize the Soma desktop app via <code>release-desktop.yml</code>; the workflow publishes per-<code>(os, arch)</code> assets plus a <code>SHA256SUMS</code> file to a <code>desktop-v*</code> Release. Users download directly from GitHub — there is no <code>curl | bash</code> bootstrap.</li><li>Build the <code>somad</code> server image via <code>release-server.yml</code>; the workflow publishes multi-arch tags to <code>ghcr.io/&lt;owner&gt;/somad</code>.</li><li>Update Helm chart values with new container tags for rendezvous, relay, or hosted bot deployments.</li><li>Use <code>helm upgrade</code> to roll out infrastructure changes; Kubernetes handles restarts and liveness probes keep pods healthy.</li><li>Monitor relay bandwidth/memory and rendezvous registration counts to plan scaling.</li></ol><p>The infrastructure components never store user content — they only facilitate peer discovery and encrypted transport — so PII risk stays on user-controlled devices while still delivering reliable connectivity.</p>',25)])])}const m=o(r,[["render",d]]);export{h as __pageData,m as default};
